import { readFileSync } from "node:fs";

const SCHEMA_VERSION = 4;
const SCHEMA_ID = `cfg-schema-v${SCHEMA_VERSION}`;
const VERSION_KEY = "schemaVersion";

const isObject = (v) => v !== null && typeof v === "object" && !Array.isArray(v);

function readLayer(path, layer) {
  if (!path) return null;
  let text;
  try {
    text = readFileSync(path, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") return null;
    throw err;
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    throw new Error(`${layer} config ${path} is not valid JSON: ${err.message}`);
  }
  if (!isObject(data)) throw new Error(`${layer} config ${path} must be a JSON object`);

  const declared = data[VERSION_KEY];
  if (declared !== undefined) {
    const match = /^cfg-schema-v(\d+)$/.exec(String(declared));
    if (!match) throw new Error(`${layer} config ${path} declares invalid schema version "${declared}"`);
    if (Number(match[1]) > SCHEMA_VERSION) {
      throw new Error(`${layer} config ${path} declares ${declared}, newer than supported ${SCHEMA_ID}`);
    }
  }
  delete data[VERSION_KEY];
  return data;
}

// Merge one layer over the target. Keys absent from `schema` warn and are still kept.
function mergeLayer(target, source, schema, layer, prefix, provenance, warnings) {
  for (const [key, value] of Object.entries(source)) {
    const path = prefix ? `${prefix}.${key}` : key;
    const known = schema !== undefined && Object.hasOwn(schema, key);
    if (!known) {
      warnings.push({ key: path, layer, message: `unknown key "${path}" in ${layer} layer` });
      target[key] = value;
      provenance[path] = layer;
      continue;
    }
    const expected = schema[key];
    if (isObject(expected) && isObject(value)) {
      if (!isObject(target[key])) target[key] = {};
      mergeLayer(target[key], value, expected, layer, path, provenance, warnings);
    } else {
      if (!isObject(expected) && value !== null && expected !== null && typeof value !== typeof expected) {
        throw new Error(`"${path}" in ${layer} layer must be ${typeof expected}, got ${typeof value}`);
      }
      target[key] = value;
      provenance[path] = layer;
    }
  }
}

/**
 * Load config in three layers: built-in defaults, project file, user file.
 * The built-in defaults double as the schema (known keys and value types).
 *
 * @param {{ defaults?: object, projectPath?: string, userPath?: string }} [options]
 * @returns {{ config: object, provenance: Record<string, "default"|"project"|"user">,
 *             warnings: {key: string, layer: string, message: string}[], schema: string }}
 */
export function loadConfig({ defaults = {}, projectPath, userPath } = {}) {
  const config = {};
  const provenance = {};
  const warnings = [];

  mergeLayer(config, structuredClone(defaults), defaults, "default", "", provenance, warnings);

  for (const [layer, path] of [["project", projectPath], ["user", userPath]]) {
    const data = readLayer(path, layer);
    if (data) mergeLayer(config, data, defaults, layer, "", provenance, warnings);
  }

  return { config, provenance, warnings, schema: SCHEMA_ID };
}
