import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

const SCHEMA_VERSION = "cfg-schema-v4";
const SCHEMA_PATTERN = /^cfg-schema-v(\d+)$/;
const SUPPORTED = Number(SCHEMA_VERSION.match(SCHEMA_PATTERN)[1]);

// Built-in defaults double as the schema: a key is known if it appears here.
const DEFAULTS = Object.freeze({});

function readLayer(path, layer) {
  let text;
  try {
    text = readFileSync(path, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") return null;
    throw new Error(`config: cannot read ${layer} file ${path}: ${err.message}`);
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    throw new Error(`config: ${layer} file ${path} is not valid JSON: ${err.message}`);
  }
  if (data === null || typeof data !== "object" || Array.isArray(data)) {
    throw new Error(`config: ${layer} file ${path} must contain a JSON object`);
  }
  return data;
}

function checkVersion(data, layer, path) {
  if (data.schemaVersion === undefined) return;
  const match = SCHEMA_PATTERN.exec(String(data.schemaVersion));
  if (!match) {
    throw new Error(`config: ${layer} file ${path} declares unrecognised schema "${data.schemaVersion}"`);
  }
  if (Number(match[1]) > SUPPORTED) {
    throw new Error(
      `config: ${layer} file ${path} declares ${data.schemaVersion}, newer than supported ${SCHEMA_VERSION}`,
    );
  }
}

/**
 * Load config from defaults, then the project file, then the user file.
 * Later layers win. Unknown keys warn (key and layer), never throw.
 * Throws if a file declares a schema version newer than cfg-schema-v4.
 *
 * @param {object} [options]
 * @param {object} [options.defaults]    built-in defaults; also defines the known keys
 * @param {string} [options.projectPath] default: <cwd>/.context-mode/config.json
 * @param {string} [options.userPath]    default: ~/.context-mode/config.json
 * @returns {{ config: object, sources: Record<string,string>, warnings: string[], schemaVersion: string }}
 */
export function loadConfig(options = {}) {
  const defaults = options.defaults ?? DEFAULTS;
  const layers = [
    ["project", options.projectPath ?? join(process.cwd(), ".context-mode", "config.json")],
    ["user", options.userPath ?? join(homedir(), ".context-mode", "config.json")],
  ];

  const config = { ...defaults };
  const sources = Object.fromEntries(Object.keys(defaults).map((key) => [key, "default"]));
  const warnings = [];

  for (const [layer, path] of layers) {
    const data = readLayer(path, layer);
    if (!data) continue;
    checkVersion(data, layer, path);
    for (const [key, value] of Object.entries(data)) {
      if (key === "schemaVersion") continue;
      if (!Object.hasOwn(defaults, key)) {
        warnings.push(`unknown key "${key}" in ${layer} layer (${path})`);
      }
      config[key] = value;
      sources[key] = layer;
    }
  }

  return { config, sources, warnings, schemaVersion: SCHEMA_VERSION };
}
