const SCHEMA_VERSION = 4;
const SCHEMA_ID = `cfg-schema-v${SCHEMA_VERSION}`;
const VERSION_KEY = "schemaVersion";

const isPlainObject = (v) => v !== null && typeof v === "object" && !Array.isArray(v);

function readLayer(path, layer) {
  if (!path) return null;
  let text;
  try {
    text = readFileSync(path, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") return null;
    throw err;
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    throw new Error(`${layer} config ${path}: invalid JSON (${err.message})`);
  }
  if (!isPlainObject(data)) {
    throw new Error(`${layer} config ${path}: top level must be an object`);
  }
  checkVersion(data[VERSION_KEY], layer, path);
  return data;
}

function checkVersion(declared, layer, path) {
  if (declared === undefined) return;
  const match = /^cfg-schema-v(\d+)$/.exec(String(declared));
  if (!match) {
    throw new Error(`${layer} config ${path}: unrecognised ${VERSION_KEY} "${declared}"`);
  }
  if (Number(match[1]) > SCHEMA_VERSION) {
    throw new Error(
      `${layer} config ${path}: declares ${declared}, newer than supported ${SCHEMA_ID}`,
    );
  }
}

// Merge `data` over `target`, recording the layer for every leaf value.
// A key is known when it exists in `defaults`; unknown keys warn and are kept out.
function mergeLayer(target, sources, data, defaults, layer, warnings, prefix = "") {
  for (const [key, value] of Object.entries(data)) {
    if (!prefix && key === VERSION_KEY) continue;
    const path = prefix + key;
    if (!Object.hasOwn(defaults, key)) {
      warnings.push({ key: path, layer, message: `unknown key "${path}" in ${layer} layer` });
      continue;
    }
    if (isPlainObject(defaults[key]) && isPlainObject(value)) {
      mergeLayer(target[key], sources, value, defaults[key], layer, warnings, `${path}.`);
    } else {
      target[key] = value;
      sources[path] = layer;
    }
  }
}

function seed(defaults, sources, prefix = "") {
  const out = {};
  for (const [key, value] of Object.entries(defaults)) {
    const path = prefix + key;
    if (isPlainObject(value)) {
      out[key] = seed(value, sources, `${path}.`);
    } else {
      out[key] = value;
      sources[path] = "default";
    }
  }
  return out;
}

/**
 * Load config in three layers: built-in defaults, project file, user file.
 * Later layers win. Unknown keys warn (key + layer) and are ignored.
 * Files declaring a schema newer than cfg-schema-v4 are refused.
 *
 * @param {{ defaults?: object, projectPath?: string, userPath?: string }} [options]
 * @returns {{ config: object, sources: Record<string,string>, warnings: Array<{key:string,layer:string,message:string}>, schema: string }}
 */
export function loadConfig({ defaults = {}, projectPath, userPath } = {}) {
  const sources = {};
  const warnings = [];
  const config = seed(defaults, sources);

  for (const [layer, path] of [["project", projectPath], ["user", userPath]]) {
    const data = readLayer(path, layer);
    if (data) mergeLayer(config, sources, data, defaults, layer, warnings);
  }

  return { config, sources, warnings, schema: SCHEMA_ID };
}
