    throw new Error(`${layer} config ${path} must be a JSON object`);
  }
  if (VERSION_KEY in data) {
    const declared = parseVersion(data[VERSION_KEY], layer);
    if (declared > SCHEMA_VERSION) {
      throw new Error(
        `${layer} config ${path} declares cfg-schema-v${declared}, newer than supported cfg-schema-v${SCHEMA_VERSION}`,
      );
    }
  }
  return data;
}

/**
 * Load config in three layers: defaults, project file, user file.
 * Later layers override earlier ones. Unknown keys (not present in `defaults`
 * or `knownKeys`) produce a warning naming the key and layer, never an error.
 *
 * @param {object} [options]
 * @param {object} [options.defaults] built-in defaults
 * @param {string} [options.projectFile] path to the project config file
 * @param {string} [options.userFile] path to the user config file
 * @param {string[]} [options.knownKeys] extra keys accepted by the schema
 * @param {Record<string, (value: unknown) => boolean>} [options.validators]
 * @returns {{ config: object, sources: Record<string, string>, warnings: string[] }}
 *   `sources` maps each key to the layer that set it.
 */
export function loadConfig({
  defaults = {},
  projectFile,
  userFile,
  knownKeys = [],
  validators = {},
} = {}) {
  const known = new Set([...Object.keys(defaults), ...knownKeys, VERSION_KEY]);
  const config = {};
  const sources = {};
  const warnings = [];

  const apply = (data, layer) => {
    for (const [key, value] of Object.entries(data)) {
      if (!known.has(key)) {
        warnings.push(`Unknown config key "${key}" in ${layer} layer`);
      }
      config[key] = value;
      sources[key] = layer;
    }
  };

  apply(defaults, "defaults");
  const layers = [
    ["project", projectFile],
    ["user", userFile],
  ];
  for (const [layer, path] of layers) {
    if (!path) continue;
    const data = readLayer(path, layer);
    if (data) apply(data, layer);
  }

  for (const [key, validate] of Object.entries(validators)) {
    if (key in config && !validate(config[key])) {
      throw new Error(
        `Invalid value for "${key}" (set by ${sources[key]} layer)`,
      );
    }
  }

  return { config, sources, warnings };
}
