import { readFileSync } from "node:fs";

const SCHEMA_VERSION = 4;
const SCHEMA_ID = `cfg-schema-v${SCHEMA_VERSION}`;
const VERSION_KEY = "schemaVersion";

const isPlainObject = (v) =>
  v !== null && typeof v === "object" && !Array.isArray(v);

function readLayerFile(path, layer) {
  let text;
  try {
    text = readFileSync(path, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") return null;
    throw err;
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    throw new Error(`${layer} config ${path}: invalid JSON (${err.message})`);
  }
  if (!isPlainObject(data)) {
    throw new Error(`${layer} config ${path}: top level must be an object`);
  }
  return data;
}

function checkVersion(data, layer, path) {
  const declared = data[VERSION_KEY];
  if (declared === undefined) return;
  const match = /^cfg-schema-v(\d+)$/.exec(String(declared));
  if (!match) {
    throw new Error(`${layer} config ${path}: unrecognised ${VERSION_KEY} "${declared}"`);
  }
  if (Number(match[1]) > SCHEMA_VERSION) {
    throw new Error(
      `${layer} config ${path}: declares ${declared}, newer than supported ${SCHEMA_ID}`,
    );
  }
}

// Merge `data` into `target`, recording the layer that set each leaf value.
// Keys absent from `schema` are skipped with a warning (never an error).
function mergeLayer(target, sources, data, schema, layer, warnings, prefix = "") {
  for (const [key, value] of Object.entries(data)) {
    const keyPath = prefix + key;
    if (!prefix && key === VERSION_KEY) continue;
    if (!Object.hasOwn(schema, key)) {
      warnings.push({ key: keyPath, layer, message: `unknown key "${keyPath}" in ${layer} layer` });
      continue;
    }
    const expected = schema[key];
    if (isPlainObject(expected)) {
      if (!isPlainObject(value)) {
        throw new Error(`${layer} layer: "${keyPath}" must be an object`);
      }
      target[key] ??= {};
      mergeLayer(target[key], sources, value, expected, layer, warnings, `${keyPath}.`);
      continue;
    }
    if (expected !== null && value !== null && typeof value !== typeof expected) {
      throw new Error(`${layer} layer: "${keyPath}" must be of type ${typeof expected}`);
    }
    target[key] = value;
    sources[keyPath] = layer;
  }
}

function recordDefaults(obj, sources, layer, prefix = "") {
  for (const [key, value] of Object.entries(obj)) {
    if (isPlainObject(value)) recordDefaults(value, sources, layer, `${prefix}${key}.`);
    else sources[`${prefix}${key}`] = layer;
  }
}

/**
 * Load config in three layers (defaults, project file, user file) and validate
 * the merged result against the shape of `defaults`.
 *
 * @param {object} options
 * @param {object} options.defaults     Built-in defaults; also defines the schema.
 * @param {string} [options.projectPath] Project config file.
 * @param {string} [options.userPath]    User config file.
 * @returns {{ config: object, sources: Record<string, string>, warnings: object[] }}
 *   `sources` maps dotted key paths to "default" | "project" | "user".
 */
export function loadConfig({ defaults, projectPath, userPath }) {
  if (!isPlainObject(defaults)) throw new Error("loadConfig: defaults must be an object");

  const config = structuredClone(defaults);
  const sources = {};
  const warnings = [];
  recordDefaults(config, sources, "default");

  for (const [layer, path] of [["project", projectPath], ["user", userPath]]) {
    if (!path) continue;
    const data = readLayerFile(path, layer);
    if (!data) continue;
    checkVersion(data, layer, path);
    mergeLayer(config, sources, data, defaults, layer, warnings);
  }

  return { config, sources, warnings };
}

