const fs = require("fs"), path = require("path");
const p = "packages/cli/lib/config/layered-loader.mjs";
fs.mkdirSync(path.dirname(p), { recursive: true });
fs.writeFileSync(p, `import { readFileSync } from "node:fs";

const SCHEMA_VERSION = "cfg-schema-v4";
const MAX_VERSION = 4;

// Known keys and their expected types. Extend as options are added.
const SCHEMA = {};

function parseVersion(v, file) {
  const m = /^cfg-schema-v(\\d+)$/.exec(String(v));
  if (!m) throw new Error(\`\${file}: invalid schemaVersion "\${v}"\`);
  return Number(m[1]);
}

function readLayer(file) {
  if (!file) return null;
  let text;
  try {
    text = readFileSync(file, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") return null;
    throw err;
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    throw new Error(\`\${file}: invalid JSON (\${err.message})\`);
  }
  if (data === null || typeof data !== "object" || Array.isArray(data)) {
    throw new Error(\`\${file}: config must be a JSON object\`);
  }
  if ("schemaVersion" in data) {
    if (parseVersion(data.schemaVersion, file) > MAX_VERSION) {
      throw new Error(
        \`\${file}: schemaVersion "\${data.schemaVersion}" is newer than \${SCHEMA_VERSION}\`,
      );
    }
    delete data.schemaVersion;
  }
  return data;
}

/**
 * Load config in three layers: defaults, project file, user file.
 * Returns { values, sources, warnings }; sources maps each key to the layer
 * that set it ("defaults" | "project" | "user").
 */
export function loadConfig({ defaults = {}, projectFile, userFile, schema = SCHEMA } = {}) {
  const layers = [
    ["defaults", defaults],
    ["project", readLayer(projectFile)],
    ["user", readLayer(userFile)],
  ];
  const values = {};
  const sources = {};
  const warnings = [];

  for (const [layer, data] of layers) {
    if (!data) continue;
    for (const [key, value] of Object.entries(data)) {
      if (!(key in schema) && layer !== "defaults") {
        warnings.push(\`unknown key "\${key}" in \${layer} layer\`);
      }
      values[key] = value;
      sources[key] = layer;
    }
  }

  for (const [key, type] of Object.entries(schema)) {
    if (key in values && typeof values[key] !== type) {
      throw new Error(
        \`config key "\${key}" (from \${sources[key]}) must be \${type}, got \${typeof values[key]}\`,
      );
    }
  }

  return { values, sources, warnings };
}
`);
